// 运行器自动生成的文件，每次运行都会覆盖，不要修改。
// Generated by the runner and overwritten on every run; do not edit.
// Helpers every dojo's tests use (as tests/dojo/mod.rs; each test file says `mod dojo;`):
// fail()/say() report a failure code the web UI has a hint for, Trace records a timeline the UI draws.
#![allow(dead_code)]
use std::time::Instant;

/// A message in both languages.
pub struct Msg {
    pub zh: String,
    pub en: String,
}

/// say(&format!("期望 {n} 个"), &format!("expected {n}"))
pub fn say(zh: &str, en: &str) -> Msg {
    Msg { zh: zh.to_string(), en: en.to_string() }
}

/// Stop the test with a failure the UI understands. `code` picks the targeted hint (byCode in
/// web/js/dojos/<id>.js); the message is shown as is, in the learner's language, so say what was
/// expected, what happened, and the likely cause.
pub fn fail(code: &str, msg: Msg) -> ! {
    panic!("DOJO_FAIL {{\"code\":{},\"msg\":{},\"msg_en\":{}}}", json(code), json(&msg.zh), json(&msg.en));
}

/// A JSON string literal.
pub fn json(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// Events for the UI's timeline: lanes with begin→end bars and marks. Save under the test's name.
pub struct Trace {
    t0: Instant,
    events: Vec<String>,
}

impl Trace {
    pub fn new() -> Self {
        Trace { t0: Instant::now(), events: Vec::new() }
    }
    /// kind is "begin", "end" or "mark"; label_en is None for language-neutral labels.
    pub fn add(&mut self, lane: &str, kind: &str, id: &str, label: &str, label_en: Option<&str>, bad: bool) {
        let t = self.t0.elapsed().as_secs_f64();
        let en = label_en.map(|e| format!(",\"label_en\":{}", json(e))).unwrap_or_default();
        self.events.push(format!("{{\"t\":{t},\"lane\":{},\"k\":{},\"id\":{},\"label\":{}{en},\"bad\":{bad}}}", json(lane), json(kind), json(id), json(label)));
    }
    pub fn save(&self, name: &str) {
        if let Ok(dir) = std::env::var("DOJO_TRACE_DIR") {
            let body = format!("{{\"t_end\":{},\"events\":[{}]}}", self.t0.elapsed().as_secs_f64(), self.events.join(","));
            let _ = std::fs::write(std::path::Path::new(&dir).join(format!("{name}.json")), body);
        }
    }
}
